    HttpService = game:GetService("HttpService"),
}

function ManualConfig.LoadSakuraWithoutAutoSave()
    local source = game:HttpGet(ManualConfig.UISourceURL)
    local loadPatchCount, savePatchCount

    source, loadPatchCount = source:gsub(
        "_config%s*=%s*Config:load%(game%.GameId%),",
        "_config = { _flags = {}, _keybinds = {}, _library = {} },"
    )

    source, savePatchCount = source:gsub(
        "Config:save%(game%.GameId,%s*Library%._config%)",
        "do end"
    )

    source = source:gsub(
        "ClientName%.Text = 'Sakura'",
        "ClientName.Text = " .. string.format("%q", ManualConfig.WindowTitle),
        1
    )

    source = source:gsub(
        "self%._text = text(%s+)Library%._config%._flags%[settings%.flag%] = self%._text",
        "self._text = text%1Textbox.Text = tostring(text or \"\")%1Library._config._flags[settings.flag] = self._text",
        1
    )

    if loadPatchCount == 0 or savePatchCount == 0 then
        error("Sakura UI changed: unable to disable its automatic config persistence")
    end

    return loadstring(source)()
end

do
    local ok, result = pcall(ManualConfig.LoadSakuraWithoutAutoSave)
    if ok then
        SakuraLib = result
    else
        warn("[nigga ap] failed to load Sakura UI: " .. tostring(result))
    end
end

