local function Notify(opts)
    opts = opts or {}
    if SakuraLib and SakuraLib.SendNotification then
        pcall(function()
            SakuraLib.SendNotification({
                title = tostring(opts.title or opts.Title or ManualConfig.WindowTitle),
                text = tostring(opts.text or opts.description or opts.Content or opts.content or ""),
                duration = tonumber(opts.duration or opts.time or opts.Duration) or 4,
            })
        end)
    end
end

