function ManualConfig.EnsureFolder()
    if type(isfolder) ~= "function" or type(makefolder) ~= "function" then
        return false, "Your executor does not support folders"
    end

    if not isfolder(ManualConfig.RootFolder) then
        makefolder(ManualConfig.RootFolder)
    end
    if not isfolder(ManualConfig.ConfigFolder) then
        makefolder(ManualConfig.ConfigFolder)
    end

    return true
end

function ManualConfig.GetPath(file_name)
    return ManualConfig.ConfigFolder .. "/" .. tostring(file_name) .. ".json"
end

function ManualConfig.SaveFile(file_name, config)
    if type(writefile) ~= "function" then
        return false, "Your executor does not support writefile"
    end

    local ok, err = pcall(function()
        local folderOK, folderError = ManualConfig.EnsureFolder()
        if not folderOK then error(folderError) end
        writefile(ManualConfig.GetPath(file_name), ManualConfig.HttpService:JSONEncode(config))
    end)

    if not ok then
        warn("failed to save config", err)
        return false, tostring(err)
    end

    return true
end

function ManualConfig.LoadFile(file_name)
    if type(isfile) ~= "function" or type(readfile) ~= "function" then
        return nil, "Your executor does not support reading files"
    end

    local path = ManualConfig.GetPath(file_name)
    if not isfile(path) then
        return nil, "No saved config exists yet"
    end

    local ok, result = pcall(function()
        return ManualConfig.HttpService:JSONDecode(readfile(path))
    end)

    if not ok then
        warn("failed to load config", result)
        return nil, tostring(result)
    end
    if type(result) ~= "table" then
        return nil, "The config file is invalid"
    end

    result._flags = type(result._flags) == "table" and result._flags or {}
    result._keybinds = type(result._keybinds) == "table" and result._keybinds or {}
    result._library = type(result._library) == "table" and result._library or {}
    return result
end

function ManualConfig.GetRuntimeConfig()
    local config = SakuraLib and SakuraLib._config or (window and window._config)
    if type(config) ~= "table" then
        config = { _flags = {}, _keybinds = {}, _library = {} }
        if SakuraLib then SakuraLib._config = config end
    end

    config._flags = type(config._flags) == "table" and config._flags or {}
    config._keybinds = type(config._keybinds) == "table" and config._keybinds or {}
    config._library = type(config._library) == "table" and config._library or {}
    return config
end

function ManualConfig.ReplaceTableContents(target, source)
    for key in pairs(target) do
        target[key] = nil
    end
    for key, value in pairs(source or {}) do
        target[key] = value
    end
end

function ManualConfig.RegisterControl(flag, defaultValue, apply)
    if flag == nil or type(apply) ~= "function" then return end
    ManualConfig.Controls[#ManualConfig.Controls + 1] = {
        flag = tostring(flag),
        default = defaultValue,
        apply = apply,
    }
end

function ManualConfig.Save()
    local ok, err = ManualConfig.SaveFile(game.GameId, ManualConfig.GetRuntimeConfig())
    if ok then
        Notify({ title = "Config", text = "Config saved successfully", duration = 3 })
    else
        Notify({ title = "Config", text = "Save failed: " .. tostring(err), duration = 5 })
    end
    return ok
end

function ManualConfig.Load()
    local loaded, err = ManualConfig.LoadFile(game.GameId)
    if not loaded then
        Notify({ title = "Config", text = "Load failed: " .. tostring(err), duration = 5 })
        return false
    end

    local runtime = ManualConfig.GetRuntimeConfig()
    ManualConfig.ReplaceTableContents(runtime._flags, loaded._flags)
    ManualConfig.ReplaceTableContents(runtime._keybinds, loaded._keybinds)
    ManualConfig.ReplaceTableContents(runtime._library, loaded._library)

    local failed = 0
    for _, control in ipairs(ManualConfig.Controls) do
        local value = runtime._flags[control.flag]
        if value == nil then value = control.default end

        local ok, applyError = pcall(
            control.apply,
            value,
            runtime._keybinds[control.flag]
        )
        if not ok then
            failed = failed + 1
            warn("[Config] failed to apply " .. control.flag, applyError)
        end
    end

    if failed == 0 then
        Notify({ title = "Config", text = "Config loaded successfully", duration = 3 })
    else
        Notify({
            title = "Config",
            text = "Config loaded; " .. tostring(failed) .. " control(s) could not be applied",
            duration = 5,
        })
    end
    return true
end

function library_register_flag(name, initial, setter)
    if initial ~= nil then
        ManualConfig.GetRuntimeConfig()._flags[name] = initial
    end
end

function library_save_flags(path)
    return ManualConfig.Save()
end

function library_load_flags(path)
    return ManualConfig.Load()
end

