local function wrap_module(sakuraModule, info)
    info = info or {}
    local m = {}

    function m:create_checkbox(i)
        i = i or {}
        if sakuraModule and sakuraModule.create_checkbox then
            local h = nil
            pcall(function()
                h = sakuraModule:create_checkbox({
                    title = tostring(i.title or "Checkbox"),
                    flag = tostring(i.flag or i.title or "Checkbox"),
                    callback = function(v)
                        if i.callback then
                            local ok, e = pcall(i.callback, v)
                            if not ok then warn("[nigga ap] checkbox callback error: " .. tostring(e)) end
                        end
                    end,
                })
            end)
            if h then
                ManualConfig.RegisterControl(
                    tostring(i.flag or i.title or "Checkbox"),
                    false,
                    function(value) h:change_state(value == true) end
                )
            end
            return h or {}
        end
        return {}
    end

    function m:create_slider(i)
        i = i or {}
        if sakuraModule and sakuraModule.create_slider then
            local mn = tonumber(i.minimum_value or i.minimum) or 0
            local mx = tonumber(i.maximum_value or i.maximum) or 100
            local dv = tonumber(i.value or i.default)
            if dv == nil then dv = mn end
            local h = nil
            pcall(function()
                h = sakuraModule:create_slider({
                    title = tostring(i.title or "Slider"),
                    flag = tostring(i.flag or i.title or "Slider"),
                    minimum_value = mn,
                    maximum_value = mx,
                    value = dv,
                    round_number = not not (i.round_number or i.round),
                    callback = function(v)
                        if i.callback then
                            local ok, e = pcall(i.callback, v)
                            if not ok then warn("[nigga ap] slider callback error: " .. tostring(e)) end
                        end
                    end,
                })
            end)
            if h then
                ManualConfig.RegisterControl(
                    tostring(i.flag or i.title or "Slider"),
                    dv,
                    function(value) h:set_percentage(tonumber(value) or dv) end
                )
            end
            return h or {}
        end
        return {}
    end

    function m:create_dropdown(i)
        i = i or {}
        if not (sakuraModule and sakuraModule.create_dropdown) then return {} end
        local opts = (type(i.options) == "table") and i.options or {}
        local settings = {
            title = tostring(i.title or "Dropdown"),
            flag = tostring(i.flag or i.title or "Dropdown"),
            options = opts,
            multi_dropdown = not not i.multi_dropdown,
            maximum_options = tonumber(i.maximum_options) or #opts,
            callback = function(v)
                if i.callback then
                    local ok, e = pcall(i.callback, v)
                    if not ok then warn("[nigga ap] dropdown callback error: " .. tostring(e)) end
                end
            end,
        }
        local mgr = nil
        pcall(function() mgr = sakuraModule:create_dropdown(settings) end)
        if not mgr then return {} end
        local dropdownFlag = tostring(i.flag or i.title or "Dropdown")
        ManualConfig.RegisterControl(
            dropdownFlag,
            opts[1],
            function(value)
                if i.multi_dropdown and type(value) == "table" then
                    local runtime = ManualConfig.GetRuntimeConfig()
                    runtime._flags[dropdownFlag] = value
                    mgr:update(value[1] or opts[1])
                else
                    mgr:update(value)
                end
            end
        )
        local wrapper = {}
        wrapper._mgr = mgr
        wrapper._settings = settings
        wrapper.maximum_options = #opts
        function wrapper:update(v) return self._mgr:update(v) end
        function wrapper:set_options(newOpts)
            local s = {}
            for k, v in pairs(self._settings) do s[k] = v end
            s.options = newOpts
            s.maximum_options = #newOpts
            local newMgr = nil
            pcall(function() newMgr = self._mgr:New(s) end)
            if newMgr then
                self._mgr = newMgr
                self._settings = s
                self.maximum_options = #newOpts
            end
            return self._mgr
        end
        return wrapper
    end

    function m:create_textbox(i)
        i = i or {}
        if sakuraModule and sakuraModule.create_textbox then
            local h = nil
            pcall(function()
                h = sakuraModule:create_textbox({
                    title = tostring(i.title or "Textbox"),
                    placeholder = tostring(i.placeholder or ""),
                    flag = tostring(i.flag or i.title or "Textbox"),
                    callback = function(v)
                        if i.callback then
                            local ok, e = pcall(i.callback, v)
                            if not ok then warn("[nigga ap] textbox callback error: " .. tostring(e)) end
                        end
                    end,
                })
            end)
            if h then
                ManualConfig.RegisterControl(
                    tostring(i.flag or i.title or "Textbox"),
                    "",
                    function(value) h:update_text(tostring(value or "")) end
                )
            end
            return h or {}
        end
        return {}
    end

    function m:create_text(i)
        i = i or {}
        if sakuraModule and sakuraModule.create_text then
            local h = nil
            pcall(function()
                h = sakuraModule:create_text({ text = tostring(i.text or i.title or "") })
            end)
            return h or {}
        end
        return {}
    end

    function m:create_paragraph(i)
        i = i or {}
        if sakuraModule and sakuraModule.create_paragraph then
            local h = nil
            pcall(function()
                h = sakuraModule:create_paragraph({
                    title = tostring(i.title or ""),
                    text = tostring(i.text or i.description or ""),
                })
            end)
            return h or {}
        end
        return {}
    end

    function m:create_divider(i)
        i = i or {}
        if sakuraModule and sakuraModule.create_divider then
            pcall(function() sakuraModule:create_divider(i) end)
        end
        return {}
    end

    function m:create_button(i)
        i = i or {}
        if sakuraModule and sakuraModule.create_feature then
            local h = nil
            pcall(function()
                h = sakuraModule:create_feature({
                    title = tostring(i.title or i.text or "Button"),
                    flag = tostring(i.flag or ("Button_" .. tostring(i.title or "Button"))),
                    disablecheck = true,
                    button_callback = function()
                        if i.callback then
                            local ok, e = pcall(i.callback)
                            if not ok then warn("[nigga ap] button callback error: " .. tostring(e)) end
                        end
                    end,
                })
            end)
            return h or {}
        end
        return {}
    end

    function m:create_keybind(i)
        return m:create_button(i)
    end

    function m:create_colorpicker(i)
        return {}
    end

    function m:create_range_slider(i)
        i = i or {}
        local mn = tonumber(i.minimum_value or i.minimum) or 0
        local mx = tonumber(i.maximum_value or i.maximum) or 100
        local a = m:create_slider({
            title = tostring(i.title or "Min"),
            flag = tostring(i.flag or "RangeMin"),
            minimum_value = mn, maximum_value = mx,
            value = (i.value and i.value.min) or mn,
            callback = function(v) if i.callback then pcall(i.callback, v, nil) end end,
        })
        local b = m:create_slider({
            title = tostring(i.title or "Max") .. " (max)",
            flag = tostring(i.flag or "RangeMax") .. "_max",
            minimum_value = mn, maximum_value = mx,
            value = (i.value and i.value.max) or mx,
            callback = function(v) if i.callback then pcall(i.callback, nil, v) end end,
        })
        return { min = a, max = b }
    end

    function m:create_dual_slider(i)
        return m:create_range_slider(i)
    end

    function m:change_state(v)
        if sakuraModule and sakuraModule.change_state then
            pcall(function() sakuraModule:change_state(v and true or false) end)
        end
    end

    return m
end

function library:create_tab(name)
    local nameStr = tostring(name)
    local sakuraTab = nil
    if window and window.create_tab then
        pcall(function()
            sakuraTab = window:create_tab(nameStr, TAB_ICONS[nameStr])
        end)
    end

    local obj = {}
    function obj:create_module(info)
        info = info or {}
        local sakuraModule = nil
        if sakuraTab and sakuraTab.create_module then
            pcall(function()
                sakuraModule = sakuraTab:create_module({
                    title = tostring(info.title or "Module"),
                    description = tostring(info.description or info.desc or ""),
                    flag = tostring(info.flag or ("Module_" .. tostring(info.title or "Module"))),
                    section = info.section or "left",
                    callback = function(state)
                        if info.callback then
                            local ok, e = pcall(info.callback, state)
                            if not ok then warn("[nigga ap] module callback error: " .. tostring(e)) end
                        end
                    end,
                })
            end)
        end
        if sakuraModule and not info.ignore_config then
            local moduleFlag = tostring(info.flag or ("Module_" .. tostring(info.title or "Module")))
            ManualConfig.RegisterControl(moduleFlag, false, function(value, keybind)
                sakuraModule:change_state(value == true)

                if keybind and sakuraModule.connect_keybind and not sakuraModule._manualConfigKeybindConnected then
                    sakuraModule:connect_keybind()
                    sakuraModule._manualConfigKeybindConnected = true
                end
            end)
        end
        return wrap_module(sakuraModule, info)
    end
    return obj
end

