local THEME = {
    container = Color3.fromRGB(40, 16, 18),
    panel = Color3.fromRGB(62, 24, 26),
    panel2 = Color3.fromRGB(78, 30, 32),
    off = Color3.fromRGB(62, 24, 26),
    hover = Color3.fromRGB(60, 22, 24),
    text = Color3.fromRGB(255, 225, 225),
    text2 = Color3.fromRGB(255, 210, 210),
    text3 = Color3.fromRGB(255, 195, 195),
}

local function _hex(c)
    return string.format("%02X%02X%02X",
        math.floor(c.R * 255 + 0.5),
        math.floor(c.G * 255 + 0.5),
        math.floor(c.B * 255 + 0.5))
end

local COLOR_MAP = {
    ["2A1C26"] = THEME.container,
    ["3A2834"] = THEME.panel,
    ["46303E"] = THEME.panel2,
    ["425073"] = THEME.off,
    ["2A3242"] = THEME.hover,
    ["FFE6F0"] = THEME.text,
    ["FFDCEB"] = THEME.text2,
    ["FFCDE1"] = THEME.text3,
    ["FF8FBC"] = ACCENT,
    ["D1DEFF"] = THEME.text2,
}

local function remapColor(c)
    return COLOR_MAP[_hex(c)] or c
end

local function recolor()
    local ui = window and window._ui
    if not ui then return end
    local container = ui:FindFirstChild("Container")
    if container then container.BackgroundColor3 = THEME.container end
    for _, obj in ipairs(ui:GetDescendants()) do
        local cn = obj.ClassName
        if cn == "Frame" or cn == "ScrollingFrame" or cn == "TextButton" then
            obj.BackgroundColor3 = remapColor(obj.BackgroundColor3)
        elseif cn == "TextLabel" or cn == "TextBox" then
            obj.TextColor3 = remapColor(obj.TextColor3)
        elseif cn == "UIStroke" then
            obj.Color = remapColor(obj.Color)
        elseif cn == "UIGradient" and obj.Color then
            local changed = false
            local pts = {}
            for _, kp in ipairs(obj.Color.Keypoints) do
                local nc = remapColor(kp.Value)
                if nc ~= kp.Value then changed = true end
                pts[#pts + 1] = ColorSequenceKeypoint.new(kp.Time, nc)
            end
            if changed then obj.Color = ColorSequence.new(pts) end
        end
    end
end

recolor()

