		if value then
			Airflow:CreateAnimation(ListFrame,0.3,nil,{
				BackgroundTransparency = 0.600
			});

			Airflow:CreateAnimation(MainFrame,0.3,nil,{
				BackgroundTransparency = 0.3
			});

