local function find_reward_remote(class_name)
    local remote_root = ReplicatedStorage:FindFirstChild("Remote")
    local remote = remote_root and remote_root:FindFirstChild(class_name, true)
    if remote and remote:IsA(class_name) then return remote end

    remote = ReplicatedStorage:FindFirstChild(class_name, true)
    if remote and remote:IsA(class_name) then return remote end
    return nil
end

local function claim_rewards_async()
    if not getgenv().AutoRewardsEnabled or auto_rewards_claiming then return end
    auto_rewards_claiming = true

    task.spawn(function()
        local remote_function = find_reward_remote("RemoteFunction")
        local remote_event = find_reward_remote("RemoteEvent")

        if getgenv().AutoRewardsDaily and remote_function then
            for day = 0, 30 do
                if not getgenv().AutoRewardsEnabled then break end
                pcall(function()
                    remote_function:InvokeServer("ClaimNewDailyLoginReward", day)
                end)
                if day % 5 == 0 then task.wait() end
            end
        end

        if getgenv().AutoRewardsCases and remote_event and getgenv().AutoRewardsEnabled then
            pcall(function()
                remote_event:FireServer("OpeningCase", true)
            end)
        end

        if getgenv().AutoRewardsSpin and remote_function and getgenv().AutoRewardsEnabled then
            pcall(function()
                remote_function:InvokeServer("SpinWheel")
            end)
        end

        auto_rewards_claiming = false
    end)
end

