function System.parry.hardware_click()
    if not _can_parry() then return end
    if not LocalPlayer.Character then return end

    local environment = getgenv and getgenv() or _G
    local click = environment and rawget(environment, "mouse1click")
    local press = environment and rawget(environment, "mouse1press")
    local release = environment and rawget(environment, "mouse1release")

    if type(click) == "function" then
        local ok = pcall(click)
        if ok then return end
    end

    if type(press) == "function" and type(release) == "function" then
        local ok = pcall(press)
        if ok then
            task.defer(function()
                pcall(release)
            end)
        end
        if ok then return end
    end

    local virtual_input_ok = _hardware_virtual_input and pcall(function()
        local mouse = UserInputService:GetMouseLocation()
        _hardware_virtual_input:SendMouseButtonEvent(mouse.X, mouse.Y, 0, true, game, 0)
        task.defer(function()
            pcall(function()
                _hardware_virtual_input:SendMouseButtonEvent(mouse.X, mouse.Y, 0, false, game, 0)
            end)
        end)
    end)

    if not virtual_input_ok then
        System.parry.execute_action()
    end
end

