local curve_selector_module = nil
local curve_selector_overlay = nil
local curve_selector_buttons = {}
local curve_selector_title = nil

local function destroy_curve_selector_overlay()
    if curve_selector_overlay then
        pcall(function()
            curve_selector_overlay:Destroy()
        end)
    end

    curve_selector_overlay = nil
    curve_selector_buttons = {}
    curve_selector_title = nil
end

local function create_curve_selector_overlay()
    if curve_selector_overlay then
        return curve_selector_overlay
    end

    if not System or not System.__properties or not System.__properties.__is_mobile then
        return nil
    end

    local T = {
        bg         = Color3.fromRGB(40, 16, 18),
        bgCard     = Color3.fromRGB(62, 24, 26),
        bgSoft     = Color3.fromRGB(78, 30, 32),
        stroke     = Color3.fromRGB(120, 42, 46),
        accent     = Color3.fromRGB(225, 45, 50),
        accentSoft = Color3.fromRGB(90, 28, 32),
        text       = Color3.fromRGB(255, 225, 225),
        textDim    = Color3.fromRGB(205, 150, 150),
        textFaint  = Color3.fromRGB(150, 100, 104),
        fontBold   = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal),
        fontMed    = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Medium, Enum.FontStyle.Normal),
        fontReg    = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal),
    }

    local function corner(ui, radius)
        local cr = Instance.new("UICorner")
        cr.CornerRadius = radius or UDim.new(0, 12)
        cr.Parent = ui
        return cr
    end

    local function stroke(ui, color, transparency, thickness)
        local st = Instance.new("UIStroke")
        st.Color = color or T.stroke
        st.Transparency = transparency or 0.4
        st.Thickness = thickness or 1.5
        st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        st.Parent = ui
        return st
    end

    local function tween(ui, duration, properties)
        return TweenService:Create(ui, TweenInfo.new(duration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), properties)
    end

    local overlay = Instance.new("ScreenGui")
    overlay.Name = "CurveModeUI"
    overlay.ResetOnSpawn = false
    overlay.IgnoreGuiInset = true
    overlay.DisplayOrder = 100
    overlay.Parent = CoreGui

    local uiScale = Instance.new("UIScale")
    uiScale.Scale = 0.8
    uiScale.Parent = overlay

    local Sheet = Instance.new("Frame")
    Sheet.Name = "CurveSheet"
    Sheet.AnchorPoint = Vector2.new(0.5, 0.5)
    Sheet.Position = UDim2.new(0.5, 0, 0.5, 0)
    Sheet.Size = UDim2.new(0.62, 0, 0, 250)
    Sheet.BackgroundColor3 = T.bg
    Sheet.BackgroundTransparency = 0.02
    Sheet.BorderSizePixel = 0
    Sheet.Visible = false
    Sheet.Parent = overlay
    corner(Sheet, UDim.new(0, 20))
    stroke(Sheet, T.accent, 0.4, 1.5)

    local smax = Instance.new("UISizeConstraint", Sheet)
    smax.MaxSize = Vector2.new(320, 280)

    local Grab = Instance.new("Frame", Sheet)
    Grab.Name = "Grab"
    Grab.AnchorPoint = Vector2.new(0.5, 0)
    Grab.Position = UDim2.new(0.5, 0, 0, 10)
    Grab.Size = UDim2.new(0, 48, 0, 5)
    Grab.BackgroundColor3 = T.stroke
    Grab.BorderSizePixel = 0
    corner(Grab, UDim.new(1, 0))

    local Header = Instance.new("Frame", Sheet)
    Header.Name = "Header"
    Header.Size = UDim2.new(1, -24, 0, 40)
    Header.Position = UDim2.new(0, 12, 0, 16)
    Header.BackgroundTransparency = 1

    local Title = Instance.new("TextLabel", Header)
    Title.Name = "Title"
    Title.BackgroundTransparency = 1
    Title.Position = UDim2.new(0, 0, 0, 0)
    Title.Size = UDim2.new(1, -90, 0, 18)
    Title.Text = "CURVE MODE"
    Title.TextColor3 = T.text
    Title.FontFace = T.fontBold
    Title.TextSize = 15
    Title.TextXAlignment = Enum.TextXAlignment.Left

    local Subtitle = Instance.new("TextLabel", Header)
    Subtitle.Name = "Subtitle"
    Subtitle.BackgroundTransparency = 1
    Subtitle.Position = UDim2.new(0, 0, 0, 20)
    Subtitle.Size = UDim2.new(1, -90, 0, 14)
    Subtitle.Text = "Tap a curve to change how you parry"
    Subtitle.TextColor3 = T.textFaint
    Subtitle.FontFace = T.fontReg
    Subtitle.TextSize = 10
    Subtitle.TextXAlignment = Enum.TextXAlignment.Left

    local CloseBtn = Instance.new("TextButton", Header)
    CloseBtn.Name = "Close"
    CloseBtn.AnchorPoint = Vector2.new(1, 0)
    CloseBtn.Position = UDim2.new(1, 0, 0, 0)
    CloseBtn.Size = UDim2.new(0, 30, 0, 30)
    CloseBtn.BackgroundColor3 = T.bgSoft
    CloseBtn.Text = "×"
    CloseBtn.FontFace = T.fontMed
    CloseBtn.TextSize = 18
    CloseBtn.TextColor3 = T.textDim
    CloseBtn.AutoButtonColor = false
    corner(CloseBtn, UDim.new(1, 0))
    stroke(CloseBtn, T.stroke, 0.5)

    local ModeCard = Instance.new("Frame", Sheet)
    ModeCard.Name = "ModeCard"
    ModeCard.Position = UDim2.new(0, 12, 0, 62)
    ModeCard.Size = UDim2.new(1, -24, 0, 40)
    ModeCard.BackgroundColor3 = T.bgCard
    ModeCard.BorderSizePixel = 0
    corner(ModeCard, UDim.new(0, 14))
    stroke(ModeCard, T.accent, 0.3, 1.5)

    local ModeDot = Instance.new("Frame", ModeCard)
    ModeDot.Name = "Dot"
    ModeDot.AnchorPoint = Vector2.new(0, 0.5)
    ModeDot.Position = UDim2.new(0, 16, 0.5, 0)
    ModeDot.Size = UDim2.new(0, 10, 0, 10)
    ModeDot.BackgroundColor3 = T.accent
    ModeDot.BorderSizePixel = 0
    corner(ModeDot, UDim.new(1, 0))

    local ModeLabel = Instance.new("TextLabel", ModeCard)
    ModeLabel.Name = "CurrentMode"
    ModeLabel.BackgroundTransparency = 1
    ModeLabel.Position = UDim2.new(0, 32, 0, 6)
    ModeLabel.Size = UDim2.new(1, -42, 0, 18)
    ModeLabel.Text = "Camera"
    ModeLabel.TextColor3 = T.text
    ModeLabel.FontFace = T.fontBold
    ModeLabel.TextSize = 13
    ModeLabel.TextXAlignment = Enum.TextXAlignment.Left

    local ModeHint = Instance.new("TextLabel", ModeCard)
    ModeHint.Name = "Hint"
    ModeHint.BackgroundTransparency = 1
    ModeHint.Position = UDim2.new(0, 32, 0, 24)
    ModeHint.Size = UDim2.new(1, -42, 0, 13)
    ModeHint.Text = "CURRENT SELECTION"
    ModeHint.TextColor3 = T.textFaint
    ModeHint.FontFace = T.fontReg
    ModeHint.TextSize = 8
    ModeHint.TextXAlignment = Enum.TextXAlignment.Left

    local gridScroller = Instance.new("ScrollingFrame", Sheet)
    gridScroller.Name = "GridScroller"
    gridScroller.Position = UDim2.new(0, 12, 0, 110)
    gridScroller.Size = UDim2.new(1, -24, 1, -118)
    gridScroller.BackgroundTransparency = 1
    gridScroller.BorderSizePixel = 0
    gridScroller.ScrollBarThickness = 3
    gridScroller.ScrollBarImageColor3 = T.accent
    gridScroller.CanvasSize = UDim2.new(0, 0, 0, 0)
    gridScroller.ClipsDescendants = true

    local grid = Instance.new("UIGridLayout", gridScroller)
    grid.CellSize = UDim2.new(0.5, -6, 0, 40)
    grid.CellPadding = UDim2.new(0, 8, 0, 6)
    grid.SortOrder = Enum.SortOrder.LayoutOrder

    local MODES = (System and System.__config and System.__config.__curve_names) or {"Camera", "Random", "Accelerated", "Backwards", "Slow", "High", "Left", "Right"}
    local MODE_DESC = {
        Camera       = "Faces the ball directly",
        Random       = "Picks a random curve each parry",
        Accelerated  = "Curves faster over time",
        Backwards    = "Curves away from the ball",
        Slow         = "A slow, wide curve",
        High         = "A tight, high curve",
        Left         = "Always curves left",
        Right        = "Always curves right",
        Straight     = "No curve at all",
        RandomTarget = "Curves toward a random player",
    }

    local current = (System and System.__properties and System.__properties.__curve_mode and System.__config and System.__config.__curve_names and System.__config.__curve_names[System.__properties.__curve_mode]) or getgenv().CurveMode or "Camera"

    local pills = {}

    local function refreshPills()
        for _, entry in pairs(pills) do
            local on = (entry.mode == current)
            entry.card.BackgroundColor3 = on and T.accentSoft or T.bgCard
            entry.label.TextColor3 = on and T.text or T.textDim
            entry.desc.TextColor3 = on and T.textDim or T.textFaint
            entry.dot.BackgroundColor3 = on and T.accent or T.stroke
            entry.stroke.Color = on and T.accent or T.stroke
        end
    end

    local function setCurrent(mode)
        current = mode
        ModeLabel.Text = mode
        ModeHint.Text = string.upper(MODE_DESC[mode] or "Active curve")
        getgenv().CurveMode = mode

        if System and System.__config and System.__config.__curve_names then
            for idx, name in ipairs(System.__config.__curve_names) do
                if name == mode then
                    System.__properties.__curve_mode = idx
                    break
                end
            end
        end

        refreshPills()
    end

    for i, mode in ipairs(MODES) do
        local card = Instance.new("TextButton", gridScroller)
        card.Name = "Mode_" .. mode
        card.LayoutOrder = i
        card.AutoButtonColor = false
        card.BackgroundColor3 = T.bgCard
        card.BorderSizePixel = 0
        card.Text = ""
        corner(card, UDim.new(0, 14))

        local cardDot = Instance.new("Frame", card)
        cardDot.Name = "Dot"
        cardDot.AnchorPoint = Vector2.new(0, 0.5)
        cardDot.Position = UDim2.new(0, 12, 0.5, 0)
        cardDot.Size = UDim2.new(0, 8, 0, 8)
        cardDot.BackgroundColor3 = T.stroke
        cardDot.BorderSizePixel = 0
        corner(cardDot, UDim.new(1, 0))

        local label = Instance.new("TextLabel", card)
        label.Name = "Label"
        label.BackgroundTransparency = 1
        label.Position = UDim2.new(0, 24, 0, 6)
        label.Size = UDim2.new(1, -28, 0, 16)
        label.Text = mode
        label.TextColor3 = T.textDim
        label.FontFace = T.fontBold
        label.TextSize = 12
        label.TextXAlignment = Enum.TextXAlignment.Left

        local desc = Instance.new("TextLabel", card)
        desc.Name = "Desc"
        desc.BackgroundTransparency = 1
        desc.Position = UDim2.new(0, 24, 0, 22)
        desc.Size = UDim2.new(1, -28, 0, 14)
        desc.Text = MODE_DESC[mode] or ""
        desc.TextColor3 = T.textFaint
        desc.FontFace = T.fontReg
        desc.TextSize = 8
        desc.TextXAlignment = Enum.TextXAlignment.Left
        desc.TextWrapped = true

        local st = stroke(card, T.stroke, 0.5)

        card.MouseButton1Click:Connect(function()
            setCurrent(mode)

            if mode_curve_dropdown then
                pcall(function() mode_curve_dropdown:update(mode) end)
            end
            if Library and Library.SendNotification then
                Library.SendNotification({ title = "Curve Mode", text = mode, duration = 1.2 })
            end
            closeSheet()
        end)

        pills[mode] = { card = card, label = label, desc = desc, dot = cardDot, stroke = st, mode = mode }
    end

    local function updateCanvas()
        local rows = math.ceil(#MODES / 2)
        gridScroller.CanvasSize = UDim2.new(0, 0, 0, rows * 64 + 10)
    end
    updateCanvas()

    local function closeSheet()
        tween(Sheet, 0.22, { BackgroundTransparency = 1 }):Play()
        task.delay(0.24, function()
            Sheet.Visible = false
        end)
    end

    local function openSheet()
        Sheet.Visible = true
        Sheet.BackgroundTransparency = 1
        setCurrent(current)
        tween(Sheet, 0.28, { BackgroundTransparency = 0.02 }):Play()
    end

    CloseBtn.MouseButton1Click:Connect(closeSheet)

    local CurveCard = Instance.new("TextButton")
    CurveCard.Name = "CurveCard"
    CurveCard.AnchorPoint = Vector2.new(0.5, 1)
    CurveCard.Position = UDim2.new(0.5, 0, 1, -16)
    CurveCard.Size = UDim2.new(0, 132, 0, 34)
    CurveCard.BackgroundColor3 = T.bgCard
    CurveCard.BackgroundTransparency = 0.04
    CurveCard.AutoButtonColor = false
    CurveCard.Text = ""
    CurveCard.Parent = overlay
    corner(CurveCard, UDim.new(0, 23))
    stroke(CurveCard, T.accent, 0.3, 1.5)

    local ccDot = Instance.new("Frame", CurveCard)
    ccDot.Name = "Dot"
    ccDot.AnchorPoint = Vector2.new(0, 0.5)
    ccDot.Position = UDim2.new(0, 16, 0.5, 0)
    ccDot.Size = UDim2.new(0, 10, 0, 10)
    ccDot.BackgroundColor3 = T.accent
    ccDot.BorderSizePixel = 0
    corner(ccDot, UDim.new(1, 0))

    local ccLabel = Instance.new("TextLabel", CurveCard)
    ccLabel.Name = "Label"
    ccLabel.BackgroundTransparency = 1
    ccLabel.Position = UDim2.new(0, 34, 0, 0)
    ccLabel.Size = UDim2.new(1, -46, 1, 0)
    ccLabel.Text = current
    ccLabel.TextColor3 = T.text
    ccLabel.FontFace = T.fontBold
    ccLabel.TextSize = 12
    ccLabel.TextXAlignment = Enum.TextXAlignment.Left

    local ccChevron = Instance.new("TextLabel", CurveCard)
    ccChevron.Name = "Chevron"
    ccChevron.BackgroundTransparency = 1
    ccChevron.AnchorPoint = Vector2.new(1, 0.5)
    ccChevron.Position = UDim2.new(1, -14, 0.5, 0)
    ccChevron.Size = UDim2.new(0, 14, 0, 16)
    ccChevron.Text = "⌃"
    ccChevron.TextColor3 = T.textDim
    ccChevron.FontFace = T.fontMed
    ccChevron.TextSize = 12

    local function syncCard()
        ccLabel.Text = current
    end

    local _origSetCurrent = setCurrent
    setCurrent = function(mode)
        _origSetCurrent(mode)
        syncCard()
    end

    CurveCard.MouseButton1Click:Connect(openSheet)

    curve_selector_overlay = overlay
    refreshPills()

    task.delay(0.1, openSheet)

    return overlay
end
