local function create_mobile_button(name, position_y, color)
    local accent = Color3.fromRGB(225, 45, 50)

    local gui = Instance.new('ScreenGui')
    gui.Name = name .. 'MobileButton'
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

    local button = Instance.new('TextButton')
    button.Size = UDim2.new(0, 128, 0, 42)
    button.Position = UDim2.new(0.5, -64, position_y, 0)
    button.BackgroundTransparency = 1
    button.AnchorPoint = Vector2.new(0.5, 0)
    button.Draggable = true
    button.AutoButtonColor = false
    button.ZIndex = 2

    local bg = Instance.new('Frame')
    bg.Size = UDim2.new(1, 0, 1, 0)
    bg.BackgroundColor3 = Color3.fromRGB(40, 16, 18)
    bg.BorderSizePixel = 0
    bg.Parent = button

    local bgCorner = Instance.new('UICorner')
    bgCorner.CornerRadius = UDim.new(0, 12)
    bgCorner.Parent = bg

    local stroke = Instance.new('UIStroke')
    stroke.Color = accent
    stroke.Thickness = 1.5
    stroke.Transparency = 0.3
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = bg

    local text = Instance.new('TextLabel')
    text.Size = UDim2.new(1, 0, 1, 0)
    text.BackgroundTransparency = 1
    text.Text = name
    text.Font = Enum.Font.GothamBold
    text.TextSize = 14
    text.TextColor3 = Color3.fromRGB(255, 225, 225)
    text.ZIndex = 3
    text.Parent = button

    button.Parent = gui
    gui.Parent = CoreGui

    return { gui = gui, button = button, text = text, bg = bg }
end

local function destroy_mobile_gui(gui_data)
    if gui_data and gui_data.gui then
        gui_data.gui:Destroy()
    end
end

local function create_triggerbot_panel()
    if System.__properties.__triggerbot_ui then
        return System.__properties.__triggerbot_ui
    end

    local T = {
        bg        = Color3.fromRGB(40, 16, 18),
        bgCard    = Color3.fromRGB(62, 24, 26),
        stroke    = Color3.fromRGB(120, 42, 46),
        accent    = Color3.fromRGB(225, 45, 50),
        accentOff = Color3.fromRGB(90, 28, 32),
        active    = Color3.fromRGB(255, 80, 85),
        text      = Color3.fromRGB(255, 225, 225),
        textDim   = Color3.fromRGB(205, 150, 150),
        textFaint = Color3.fromRGB(150, 100, 104),
        fontBold  = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal),
        fontMed   = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Medium, Enum.FontStyle.Normal),
        fontReg   = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal),
    }

    local function corner(ui, r)
        local c = Instance.new("UICorner")
        c.CornerRadius = r or UDim.new(0, 12)
        c.Parent = ui
        return c
    end

    local function stroke(ui, color, tr)
        local s = Instance.new("UIStroke")
        s.Color = color or T.stroke
        s.Transparency = tr or 0.4
        s.Thickness = 1.5
        s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        s.Parent = ui
        return s
    end

    local ScreenGui = Instance.new('ScreenGui')
    ScreenGui.Name = "TriggerbotPanel"
    ScreenGui.ResetOnSpawn = false
    ScreenGui.IgnoreGuiInset = true
    ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    ScreenGui.Parent = CoreGui

    local UI_SCALE = 0.8
    local uiScale = Instance.new("UIScale")
    uiScale.Scale = UI_SCALE
    uiScale.Parent = ScreenGui

    local Frame = Instance.new('Frame')
    Frame.Name = "TriggerbotFrame"
    Frame.Size = UDim2.new(0, 160, 0, 120)
    Frame.Position = UDim2.new(0.5, -80, 0.56, 0)
    Frame.BackgroundColor3 = T.bg
    Frame.BackgroundTransparency = 0.03
    Frame.BorderSizePixel = 0
    Frame.Parent = ScreenGui
    corner(Frame, UDim.new(0, 16))
    local FrameStroke = stroke(Frame, T.accent, 0.3)

    local Header = Instance.new('Frame', Frame)
    Header.Name = "Header"
    Header.Size = UDim2.new(1, 0, 0, 34)
    Header.BackgroundTransparency = 1

    local AccentBar = Instance.new('Frame', Header)
    AccentBar.Position = UDim2.new(0, 12, 0, 8)
    AccentBar.Size = UDim2.new(0, 4, 0, 18)
    AccentBar.BackgroundColor3 = T.accent
    AccentBar.BorderSizePixel = 0
    corner(AccentBar, UDim.new(1, 0))

    local Title = Instance.new('TextLabel', Header)
    Title.Name = 'Title'
    Title.BackgroundTransparency = 1
    Title.Position = UDim2.new(0, 24, 0, 0)
    Title.Size = UDim2.new(1, -32, 1, 0)
    Title.FontFace = T.fontBold
    Title.Text = "Triggerbot"
    Title.TextColor3 = T.text
    Title.TextSize = 14
    Title.TextXAlignment = Enum.TextXAlignment.Left

    local StatusPill = Instance.new('Frame', Frame)
    StatusPill.Name = "Status"
    StatusPill.AnchorPoint = Vector2.new(0.5, 0.5)
    StatusPill.Position = UDim2.new(0.5, 0, 0.5, -2)
    StatusPill.Size = UDim2.new(1, -24, 0, 42)
    StatusPill.BackgroundColor3 = T.bgCard
    StatusPill.BorderSizePixel = 0
    corner(StatusPill, UDim.new(0, 12))
    stroke(StatusPill, T.stroke, 0.5)

    local StatusDot = Instance.new('Frame', StatusPill)
    StatusDot.Name = "Dot"
    StatusDot.AnchorPoint = Vector2.new(0, 0.5)
    StatusDot.Position = UDim2.new(0, 14, 0.5, 0)
    StatusDot.Size = UDim2.new(0, 10, 0, 10)
    StatusDot.BackgroundColor3 = T.textFaint
    StatusDot.BorderSizePixel = 0
    corner(StatusDot, UDim.new(1, 0))

    local StatusLabel = Instance.new('TextLabel', StatusPill)
    StatusLabel.Name = "Label"
    StatusLabel.BackgroundTransparency = 1
    StatusLabel.Position = UDim2.new(0, 30, 0, 0)
    StatusLabel.Size = UDim2.new(1, -38, 1, 0)
    StatusLabel.Text = "DISABLED"
    StatusLabel.FontFace = T.fontBold
    StatusLabel.TextSize = 15
    StatusLabel.TextColor3 = T.textDim
    StatusLabel.TextXAlignment = Enum.TextXAlignment.Left

    local ToggleBtn = Instance.new('TextButton')
    ToggleBtn.Name = 'Toggle'
    ToggleBtn.Size = UDim2.new(1, -24, 0, 34)
    ToggleBtn.Position = UDim2.new(0, 12, 1, -42)
    ToggleBtn.BackgroundColor3 = T.accentOff
    ToggleBtn.BorderSizePixel = 0
    ToggleBtn.FontFace = T.fontBold
    ToggleBtn.Text = 'ENABLE'
    ToggleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
    ToggleBtn.TextSize = 14
    ToggleBtn.AutoButtonColor = false
    ToggleBtn.Parent = Frame
    corner(ToggleBtn, UDim.new(0, 12))
    local ToggleStroke = stroke(ToggleBtn, T.stroke, 0.5)

    local dragging = false
    local dragStart
    local startPos
    Header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = Frame.Position
        end
    end)
    Header.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            local d = (input.Position - dragStart) / UI_SCALE
            Frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = false
        end
    end)

    local function update_button(active)
        if active then
            ToggleBtn.Text = 'DISABLE'
            ToggleBtn.BackgroundColor3 = T.active
            ToggleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
            ToggleStroke.Color = T.active
            StatusLabel.Text = 'ACTIVE'
            StatusLabel.TextColor3 = T.active
            StatusDot.BackgroundColor3 = T.active
            FrameStroke.Color = T.active
        else
            ToggleBtn.Text = 'ENABLE'
            ToggleBtn.BackgroundColor3 = T.accent
            ToggleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
            ToggleStroke.Color = T.accent
            StatusLabel.Text = 'DISABLED'
            StatusLabel.TextColor3 = T.textDim
            StatusDot.BackgroundColor3 = T.textFaint
            FrameStroke.Color = T.accent
        end
    end

    ToggleBtn.MouseButton1Click:Connect(function()
        if System then
            local newState = not System.__properties.__triggerbot_enabled
            System.__properties.__triggerbot_enabled = newState
            if System.triggerbot and System.triggerbot.enable then
                pcall(System.triggerbot.enable, newState)
            end
            update_button(newState)
            if getgenv().TriggerbotNotify then
                send_notification("Triggerbot", newState and 'ON' or 'OFF', 2)
            end
        end
    end)

    System.__properties.__triggerbot_ui = {
        gui = ScreenGui,
        frame = Frame,
        button = ToggleBtn,
        title = Title,
        update = update_button
    }

    update_button(not not System.__properties.__triggerbot_enabled)

    return System.__properties.__triggerbot_ui
end

do
    local initOk, initError = pcall(function()
        local playerOptions = {}
        local playerMap = {}
        local labelByPlayer = {}

        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local label = "@" .. tostring(player.DisplayName) .. " (" .. player.Name .. ")"
                table.insert(playerOptions, label)
                playerMap[label] = player.Name
                labelByPlayer[player.Name] = label
            end
        end

        table.sort(playerOptions)
        if #playerOptions == 0 then
            playerOptions[1] = "No Players Online"
        end

        getgenv()._ZX_TargetLockPlayerMap = playerMap
        getgenv()._ZX_TargetLockLabelByPlayer = labelByPlayer
        getgenv().TargetLockEnabled = getgenv().TargetLockEnabled or false
        getgenv().TargetLockAutoSwitch = getgenv().TargetLockAutoSwitch or false
        getgenv().TargetLockHighlight = getgenv().TargetLockHighlight or false

        getgenv()._ZX_GetTargetLockCharacter = function()
            local playerName = getgenv().TargetLockPlayerName
            if type(playerName) ~= "string" or playerName == "" then return nil end
            local player = Players:FindFirstChild(playerName)
            if not player or player == LocalPlayer then return nil end
            local character = player.Character or (Alive and Alive:FindFirstChild(playerName))
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not character or not humanoid or humanoid.Health <= 0 then return nil end
            return character
        end

        getgenv()._ZX_SelectTargetLockFallback = function()
            local localCharacter = LocalPlayer.Character
            local localRoot = localCharacter and (localCharacter:FindFirstChild("HumanoidRootPart") or localCharacter.PrimaryPart)
            local bestPlayer = nil
            local bestDistance = math.huge

            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= LocalPlayer then
                    local character = player.Character
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                    local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
                    if humanoid and humanoid.Health > 0 and root then
                        local distance = localRoot and (localRoot.Position - root.Position).Magnitude or 0
                        if distance < bestDistance then
                            bestDistance = distance
                            bestPlayer = player
                        end
                    end
                end
            end

            if not bestPlayer then
                getgenv().TargetLockPlayerName = nil
                return nil
            end

            getgenv().TargetLockPlayerName = bestPlayer.Name
            local label = getgenv()._ZX_TargetLockLabelByPlayer[bestPlayer.Name]
            local dropdown = getgenv()._ZX_TargetLockDropdown
            if label and dropdown and dropdown.update then
                pcall(function() dropdown:update(label) end)
            end
            return bestPlayer.Character
        end

        getgenv()._ZX_ClearTargetLockHighlight = function()
            if getgenv()._ZX_TargetLockHighlightInstance then
                pcall(function() getgenv()._ZX_TargetLockHighlightInstance:Destroy() end)
                getgenv()._ZX_TargetLockHighlightInstance = nil
            end
        end

        getgenv()._ZX_UpdateTargetLockHighlight = function()
            if not getgenv().TargetLockEnabled or not getgenv().TargetLockHighlight then
                getgenv()._ZX_ClearTargetLockHighlight()
                return
            end

            local character = getgenv()._ZX_GetTargetLockCharacter()
            if not character then
                getgenv()._ZX_ClearTargetLockHighlight()
                return
            end

            local highlight = getgenv()._ZX_TargetLockHighlightInstance
            if not highlight or not highlight.Parent then
                highlight = Instance.new("Highlight")
                highlight.Name = "ZX_TargetLockHighlight"
                getgenv()._ZX_TargetLockHighlightInstance = highlight
            end

            local pulse = (math.sin(os.clock() * 5) + 1) * 0.5
            highlight.Enabled = true
            highlight.FillColor = Color3.fromRGB(255, 35, 55)
            highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
            highlight.FillTransparency = 0.10 + pulse * 0.12
            highlight.OutlineTransparency = 0
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Adornee = character
            highlight.Parent = character
        end

        local targetLockModule = AutoparryTab:create_module({
            title = "Target Lock",
            description = "Locks every parry onto the selected player",
            flag = "TargetLockModule",
            section = "right",
            callback = function(state)
                getgenv().TargetLockEnabled = state
                if state and getgenv().TargetLockAutoSwitch and not getgenv()._ZX_GetTargetLockCharacter() then
                    getgenv()._ZX_SelectTargetLockFallback()
                end
                getgenv()._ZX_UpdateTargetLockHighlight()
            end
        })

        getgenv()._ZX_TargetLockDropdown = targetLockModule:create_dropdown({
            title = "Target Player",
            flag = "TargetLockPlayer",
            options = playerOptions,
            multi_dropdown = false,
            maximum_options = math.min(10, #playerOptions),
            callback = function(value)
                local label = typeof(value) == "string" and value or (value and value.Name)
                local playerName = label and getgenv()._ZX_TargetLockPlayerMap[label]
                if playerName then
                    getgenv().TargetLockPlayerName = playerName
                elseif label == "No Players Online" then
                    getgenv().TargetLockPlayerName = nil
                end
                getgenv()._ZX_UpdateTargetLockHighlight()
            end
        })

        targetLockModule:create_checkbox({
            title = "Auto Switch",
            flag = "TargetLockAutoSwitch",
            callback = function(value)
                getgenv().TargetLockAutoSwitch = value
                if value and getgenv().TargetLockEnabled and not getgenv()._ZX_GetTargetLockCharacter() then
                    getgenv()._ZX_SelectTargetLockFallback()
                end
            end
        })

        targetLockModule:create_checkbox({
            title = "Target Highlight",
            flag = "TargetLockHighlight",
            callback = function(value)
                getgenv().TargetLockHighlight = value
                getgenv()._ZX_UpdateTargetLockHighlight()
            end
        })

        if getgenv()._ZX_TargetLockMonitorConnection then
            pcall(function() getgenv()._ZX_TargetLockMonitorConnection:Disconnect() end)
        end

        local monitorAccumulator = 0
        getgenv()._ZX_TargetLockMonitorConnection = RunService.Heartbeat:Connect(function(delta)
            monitorAccumulator = monitorAccumulator + delta
            if monitorAccumulator < 0.25 then return end
            monitorAccumulator = 0

            if not getgenv().TargetLockEnabled then
                getgenv()._ZX_ClearTargetLockHighlight()
                return
            end

            if getgenv().TargetLockAutoSwitch and not getgenv()._ZX_GetTargetLockCharacter() then
                getgenv()._ZX_SelectTargetLockFallback()
            end

            getgenv()._ZX_UpdateTargetLockHighlight()
        end)
    end)

    if not initOk then
        warn("[Target Lock] UI initialization failed:", tostring(initError))
    end
end

local triggerbot_module = AutoparryTab:create_module({
    title = "Triggerbot",
    description = "Triggerbot Settings",
    flag = "TriggerbotModule",
    section = "right",
    callback = function(state)
        if (type("")=="string") and (System) then
            if state then
                                if System and System.__properties and System.__properties.__is_mobile then
                    if not System.__properties.__triggerbot_ui then
                        create_triggerbot_panel()
                    end

                    System.__properties.__triggerbot_enabled = false
                    if (0==0) and (System.__properties.__triggerbot_ui and System.__properties.__triggerbot_ui.update) then
                        System.__properties.__triggerbot_ui.update(false)
                    end
                else
                    System.__properties.__triggerbot_enabled = state
                    if System.triggerbot and System.triggerbot.enable then pcall(System.triggerbot.enable, state) end
                    if ((1+1)==2) and (getgenv().TriggerbotNotify) then
                        send_notification("Triggerbot", "ON", 2)
                    end
                end

            else
                if System.triggerbot and System.triggerbot.enable then pcall(System.triggerbot.enable, false) end
                if getgenv().TriggerbotNotify then
                    send_notification("Triggerbot", "OFF", 2)
                end
                if (({})~=nil) and (System.__properties.__triggerbot_ui and System.__properties.__triggerbot_ui.gui) then
                    pcall(function()
                        System.__properties.__triggerbot_ui.gui:Destroy()
                    end)
                    System.__properties.__triggerbot_ui = nil
                end
                if System.__properties.__mobile_guis.triggerbot then
                    destroy_mobile_gui(System.__properties.__mobile_guis.triggerbot)
                    System.__properties.__mobile_guis.triggerbot = nil
                end
            end
        end
    end
})

