                    local s = Instance.new("UIStroke")
                    s.Color = color or T.stroke
                    s.Transparency = tr or 0.4
                    s.Thickness = 1.5
                    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                    s.Parent = ui
                    return s
                end

                local ScreenGui = Instance.new("ScreenGui", CoreGui)
                ScreenGui.Name = "ManualSpamPanel"
                ScreenGui.ResetOnSpawn = false
                ScreenGui.IgnoreGuiInset = true
                ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling

                local UI_SCALE = 0.8
                local uiScale = Instance.new("UIScale")
                uiScale.Scale = UI_SCALE
                uiScale.Parent = ScreenGui

                local SpamFrame = Instance.new("Frame", ScreenGui)
                SpamFrame.Name = "SpamFrame"
                SpamFrame.Size = UDim2.new(0, 160, 0, 120)
                SpamFrame.Position = UDim2.new(0.5, -80, 0.34, 0)
                SpamFrame.BackgroundColor3 = T.bg
                SpamFrame.BackgroundTransparency = 0.03
                SpamFrame.BorderSizePixel = 0
                SpamFrame.Visible = true
                corner(SpamFrame, UDim.new(0, 16))
                local SpamStroke = stroke(SpamFrame, T.accent, 0.3)

                local SpamHeader = Instance.new("Frame", SpamFrame)
                SpamHeader.Name = "Header"
                SpamHeader.Size = UDim2.new(1, 0, 0, 34)
                SpamHeader.BackgroundTransparency = 1

                local SpamAccentBar = Instance.new("Frame", SpamHeader)
                SpamAccentBar.Position = UDim2.new(0, 12, 0, 8)
                SpamAccentBar.Size = UDim2.new(0, 4, 0, 18)
                SpamAccentBar.BackgroundColor3 = T.accent
                SpamAccentBar.BorderSizePixel = 0
                corner(SpamAccentBar, UDim.new(1, 0))

                local SpamTitleLbl = Instance.new("TextLabel", SpamHeader)
                SpamTitleLbl.Name = "Title"
                SpamTitleLbl.BackgroundTransparency = 1
                SpamTitleLbl.Position = UDim2.new(0, 24, 0, 0)
                SpamTitleLbl.Size = UDim2.new(1, -32, 1, 0)
