                StatusPill.Position = UDim2.new(0.5, 0, 0.5, -2)
                StatusPill.Size = UDim2.new(1, -24, 0, 42)
                StatusPill.BackgroundColor3 = T.bgCard
                StatusPill.BorderSizePixel = 0
                corner(StatusPill, UDim.new(0, 12))
                stroke(StatusPill, T.stroke, 0.5)

                local StatusDot = Instance.new("Frame", StatusPill)
                StatusDot.AnchorPoint = Vector2.new(0, 0.5)
                StatusDot.Position = UDim2.new(0, 14, 0.5, 0)
                StatusDot.Size = UDim2.new(0, 10, 0, 10)
                StatusDot.BackgroundColor3 = T.textFaint
                StatusDot.BorderSizePixel = 0
                corner(StatusDot, UDim.new(1, 0))

                local StatusLabel = Instance.new("TextLabel", StatusPill)
                StatusLabel.BackgroundTransparency = 1
                StatusLabel.Position = UDim2.new(0, 30, 0, 0)
                StatusLabel.Size = UDim2.new(1, -38, 1, 0)
                StatusLabel.Text = "DISABLED"
                StatusLabel.FontFace = T.fontBold
                StatusLabel.TextSize = 15
                StatusLabel.TextColor3 = T.textDim
                StatusLabel.TextXAlignment = Enum.TextXAlignment.Left

                local SpamToggleBtn = Instance.new("TextButton", SpamFrame)
                SpamToggleBtn.Size = UDim2.new(1, -24, 0, 34)
                SpamToggleBtn.Position = UDim2.new(0, 12, 1, -42)
                SpamToggleBtn.Text = "ENABLE"
                SpamToggleBtn.BackgroundColor3 = T.accentOff
                SpamToggleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                SpamToggleBtn.BorderSizePixel = 0
                SpamToggleBtn.FontFace = T.fontBold
                SpamToggleBtn.TextSize = 14
                SpamToggleBtn.AutoButtonColor = false
                corner(SpamToggleBtn, UDim.new(0, 12))
                local SpamToggleStroke = stroke(SpamToggleBtn, T.stroke, 0.5)

                local dragging = false
                local dragStart = nil
                local startPos = nil

                SpamHeader.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        dragging = true
                        dragStart = input.Position
                        startPos = SpamFrame.Position
                    end
                end)
                SpamHeader.InputChanged:Connect(function(input)
                    if not dragging then return end
                    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                        local delta = (input.Position - dragStart) / UI_SCALE
                        SpamFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                    end
                end)
                UserInputService.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        dragging = false
                    end
                end)

                local SpamActive = false

                local function UpdateSpamColors(active)
                    if active then
                        SpamStroke.Color = T.active
                        StatusLabel.Text = "ACTIVE"
                        StatusLabel.TextColor3 = T.active
                        StatusDot.BackgroundColor3 = T.active
                        SpamToggleBtn.Text = "DISABLE"
                        SpamToggleBtn.BackgroundColor3 = T.active
                        SpamToggleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                        SpamToggleStroke.Color = T.active
                    else
                        SpamStroke.Color = T.accent
                        StatusLabel.Text = "DISABLED"
                        StatusLabel.TextColor3 = T.textDim
                        StatusDot.BackgroundColor3 = T.textFaint
                        SpamToggleBtn.Text = "ENABLE"
                        SpamToggleBtn.BackgroundColor3 = T.accent
                        SpamToggleBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
                        SpamToggleStroke.Color = T.accent
                    end
                end

                SpamToggleBtn.MouseButton1Click:Connect(function()
                    SpamActive = not SpamActive
                    UpdateSpamColors(SpamActive)
                    if SpamActive then
                        if System and System.manual_spam and System.manual_spam.start then pcall(System.manual_spam.start) end
                    else
                        if System and System.manual_spam and System.manual_spam.stop then pcall(System.manual_spam.stop) end
                    end
                end)

                System.__properties.__manual_spam_ui = {
                    gui = ScreenGui,
                    frame = SpamFrame,
                    button = SpamToggleBtn,
                    title = SpamTitleLbl,
                    active = true,
                    update = UpdateSpamColors
                }
                System.__properties.__manual_spam_ui_created = true

                SpamActive = false
                UpdateSpamColors(false)
            end
        else
            if System and System.manual_spam and System.manual_spam.stop then
                pcall(System.manual_spam.stop)
            end

            if ((1+1)==2) and (System.__properties.__manual_spam_ui and System.__properties.__manual_spam_ui.gui) then
                pcall(function()
                    System.__properties.__manual_spam_ui.gui:Destroy()
                end)
                System.__properties.__manual_spam_ui = nil
                System.__properties.__manual_spam_ui_created = false
            end
        end
    end
})

