                    if not table.find(newOptions, SelectedPlayerFollow) then
                        SelectedPlayerFollow = newOptions[1]
                        followDropdown:update(SelectedPlayerFollow)
                    end
                else
                    SelectedPlayerFollow = nil
                end
            end
            lastOptionsString = newOptionsString
        end
        updateTimer = 0
    end
end)

